      "path": "app.js",
      "oldString": "function updateFavoriteUI() {
  const btn = $('#favorite');
  btn.setAttribute('aria-pressed', state.isFav);
  btn.setAttribute('aria-label', state.isFav ? '수업 찜 취소' : '수업 찜하기');
  const img = $('img', btn);
  if (state.isFav) {
    img.src = 'assets/icons/HeartFilled.svg';
  } else {
    img.src = 'assets/icons/Heart.svg';
  }
}",
      "newString": "function updateFavoriteUI() {
  const btn = $('#favorite');
  btn.setAttribute('aria-pressed', state.isFav);
  btn.setAttribute('aria-label', state.isFav ? '수업 찜 취소' : '수업 찜하기');
  const img = $('img', btn);
  if (state.isFav) {
    img.style.filter = 'invert(30%) sepia(70%) saturate(2200%) hue-rotate(226deg)';
  } else {
    img.style.filter = '';
  }
}"
